"""Run-time library for code generated by vba2py: the part of Excel's object model that the
converted macros use, on top of openpyxl, with Excel's own names (Range, Cells, Selection,
FormatConditions, ...) so generated code reads like the macro it came from.

What this is not: Excel. It keeps track of the active workbook, sheet and selection exactly as
the macro's statements change them, but
  - formulas are calculated only by the small evaluator below (a fixed list of functions);
    anything else raises NotConverted instead of guessing;
  - AutoFit estimates widths from text length; Excel measures the rendered font;
  - saving goes through openpyxl, which does not keep everything Excel keeps (charts, shapes,
    pivot caches, some formatting). Save to a copy and compare before trusting it.
Anything unsupported raises NotConverted. Nothing is silently skipped.
"""
import datetime as _dt
import fnmatch
import os
import re
from copy import copy

import openpyxl
from openpyxl.formatting.rule import Rule
from openpyxl.formula.translate import Translator
from openpyxl.styles import Color, Font, PatternFill
from openpyxl.styles.differential import DifferentialStyle
from openpyxl.utils import column_index_from_string, get_column_letter

MAX_ROW, MAX_COL = 1048576, 16384
xlUp, xlDown, xlToLeft, xlToRight = -4162, -4121, -4159, -4161
xlPasteAll, xlPasteValues, xlPasteFormats, xlPasteFormulas = -4104, -4163, -4122, -4123
xlCellValue, xlExpression = 1, 2
_OPERATORS = {1: "between", 2: "notBetween", 3: "equal", 4: "notEqual", 5: "greaterThan", 6: "lessThan",
              7: "greaterThanOrEqual", 8: "lessThanOrEqual"}


class NotConverted(Exception):
    """This statement or feature has no deterministic openpyxl equivalent here."""


class XlError:
    def __init__(self, code):
        self.code = code

    def __repr__(self):
        return self.code

    def __eq__(self, other):
        return isinstance(other, XlError) and other.code == self.code

    def __hash__(self):
        return hash(self.code)


NA = XlError("#N/A")


# ============================================================================= VBA values and operators
def val(x):
    """Value of a range-like object (its default property), else the thing itself."""
    return x.Value if isinstance(x, Rng) else x


def _empty(x):
    return x is None or x == ""


def _n(x):
    x = val(x)
    if x is None or x == "":
        return 0
    if isinstance(x, bool):
        return -1 if x else 0
    if isinstance(x, (int, float)):
        return x
    if isinstance(x, (_dt.datetime, _dt.date)):
        return _serial(x)
    try:
        f = float(str(x).replace(",", ""))
        return int(f) if f.is_integer() else f
    except ValueError:
        raise TypeError("Type mismatch: %r is not a number" % (x,))


def _s(x):
    x = val(x)
    if x is None:
        return ""
    if isinstance(x, bool):
        return "True" if x else "False"
    if isinstance(x, float):
        return str(int(x)) if x.is_integer() and abs(x) < 1e15 else repr(float("%.15g" % x))
    if isinstance(x, _dt.datetime):
        return x.strftime("%d/%m/%Y %H:%M:%S") if (x.hour or x.minute or x.second) else x.strftime("%d/%m/%Y")
    return str(x)


def _cmp(a, b, text=False):
    a, b = val(a), val(b)
    if isinstance(a, XlError) or isinstance(b, XlError):
        raise TypeError("Type mismatch: comparison with a cell error %s" % (a if isinstance(a, XlError) else b))
    if isinstance(a, str) or isinstance(b, str):
        if isinstance(a, str) and isinstance(b, str) or _empty(a) or _empty(b):
            a, b = _s(a), _s(b)
            if text:
                a, b = a.lower(), b.lower()
        else:
            a, b = _n(a), _n(b)
    else:
        a, b = _n(a), _n(b)
    return (a > b) - (a < b)


COMPARE_TEXT = [False]          # set by generated code for a module with Option Compare Text


def eq(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) == 0


def ne(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) != 0


def lt(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) < 0


def le(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) <= 0


def gt(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) > 0


def ge(a, b):
    return _cmp(a, b, COMPARE_TEXT[0]) >= 0


def truth(x):
    x = val(x)
    if isinstance(x, str):
        return x.strip().lower() == "true" or (x.strip() not in ("", "false") and _n(x) != 0)
    return bool(_n(x))


def cat(*parts):
    return "".join(_s(p) for p in parts)


def add(a, b):
    a, b = val(a), val(b)
    return a + b if isinstance(a, str) and isinstance(b, str) else _n(a) + _n(b)


def sub(a, b):
    return _n(a) - _n(b)


def mul(a, b):
    return _n(a) * _n(b)


def div(a, b):
    if _n(b) == 0:
        raise ZeroDivisionError("Division by zero")
    return _n(a) / _n(b)


def _bankers(x):
    return int(round(x))                  # Python's round is round-half-to-even, as VBA's CInt/CLng/Round


def idiv(a, b):
    a, b = _bankers(_n(a)), _bankers(_n(b))
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def mod(a, b):
    a, b = _bankers(_n(a)), _bankers(_n(b))
    return a - b * idiv(a, b)


def pow_(a, b):
    return _n(a) ** _n(b)


def neg(a):
    return -_n(a)


def like(s, pattern):
    return fnmatch.fnmatchcase(_s(s), _s(pattern).replace("#", "[0-9]"))


def vba_range(start, stop, step=1):
    start, stop, step = _n(start), _n(stop), _n(step)
    i = start
    while (step > 0 and i <= stop) or (step < 0 and i >= stop):
        yield i
        i += step


def each(coll):
    return iter(coll)


def Len(s):
    return len(_s(s))


def Left(s, n):
    return _s(s)[:max(int(_n(n)), 0)]


def Right(s, n):
    n = int(_n(n))
    return _s(s)[-n:] if n > 0 else ""


def Mid(s, start, length=None):
    s, start = _s(s), int(_n(start)) - 1
    return s[start:] if length is None else s[start:start + int(_n(length))]


def Trim(s):
    return _s(s).strip(" ")


def LTrim(s):
    return _s(s).lstrip(" ")


def RTrim(s):
    return _s(s).rstrip(" ")


def UCase(s):
    return _s(s).upper()


def LCase(s):
    return _s(s).lower()


def InStr(*a):
    start, s, t = (a[0], a[1], a[2]) if len(a) >= 3 and not isinstance(val(a[0]), str) else (1, a[0], a[1])
    text = len(a) == 4 and _n(a[3]) == 1 or len(a) == 3 and isinstance(val(a[0]), str) and _n(a[2]) == 1
    s, t = (_s(s).lower(), _s(t).lower()) if text or COMPARE_TEXT[0] else (_s(s), _s(t))
    return s.find(t, int(_n(start)) - 1) + 1


def InStrRev(s, t, start=-1):
    return _s(s).rfind(_s(t)) + 1


def Replace(s, find, repl, start=1, count=-1, compare=0):
    if _n(compare) == 1:
        return re.sub(re.escape(_s(find)), lambda m: _s(repl), _s(s), count=max(int(_n(count)), 0), flags=re.I)
    return _s(s).replace(_s(find), _s(repl), int(_n(count)))


def CStr(x):
    return _s(x)


def CLng(x):
    return _bankers(_n(x))


CInt = CLng


def CDbl(x):
    return float(_n(x))


def Val(s):
    m = re.match(r"\s*[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?", _s(s).replace(" ", ""))
    return float(m.group(0)) if m else 0


def Int(x):
    import math
    return math.floor(_n(x))


def Fix(x):
    return int(_n(x))


def Abs(x):
    return abs(_n(x))


def Round(x, digits=0):
    return round(_n(x), int(_n(digits)))


def IIf(c, a, b):
    return a if truth(c) else b


def IsEmpty(x):
    return val(x) is None


def IsNumeric(x):
    try:
        _n(x)
        return not _empty(val(x))
    except TypeError:
        return False


def IsError(x):
    return isinstance(val(x), XlError)


def Chr(n):
    return chr(int(_n(n)))


def Asc(s):
    return ord(_s(s)[0])


def Space(n):
    return " " * int(_n(n))


def Split(s, sep=" "):
    return _s(s).split(_s(sep))


def Join(items, sep=" "):
    return _s(sep).join(_s(i) for i in items)


def Array(*items):
    return list(items)


def UBound(a, dim=1):
    return len(a) - 1


def LBound(a, dim=1):
    return 0


_EPOCH = _dt.datetime(1899, 12, 30)


def _serial(d):
    if not isinstance(d, _dt.datetime):
        d = _dt.datetime(d.year, d.month, d.day)
    delta = d - _EPOCH
    return delta.days + delta.seconds / 86400.0 if delta.seconds else delta.days


def _date(x):
    x = val(x)
    if isinstance(x, _dt.datetime):
        return x
    if isinstance(x, _dt.date):
        return _dt.datetime(x.year, x.month, x.day)
    if isinstance(x, (int, float)) and not isinstance(x, bool):
        return _EPOCH + _dt.timedelta(days=x)
    for fmt in ("%Y-%m-%d", "%d-%b-%y", "%d-%b-%Y", "%d %b %Y", "%d %B %Y", "%Y/%m/%d"):
        try:
            return _dt.datetime.strptime(str(x).strip(), fmt)
        except ValueError:
            pass
    raise NotConverted("DateValue(%r): this text needs the PC's regional settings to be read as a date" % (x,))


def DateValue(x):
    d = _date(x)
    return _dt.datetime(d.year, d.month, d.day)


def DateSerial(y, m, d):
    y, m, d = int(_n(y)), int(_n(m)), int(_n(d))
    return _dt.datetime(y + (m - 1) // 12, (m - 1) % 12 + 1, 1) + _dt.timedelta(days=d - 1)


def Year(x):
    return _date(x).year


def Month(x):
    return _date(x).month


def Day(x):
    return _date(x).day


_FMT = [("yyyy", "%Y"), ("yy", "%y"), ("mmmm", "%B"), ("mmm", "%b"), ("mm", "%m"), ("dd", "%d"), ("hh", "%H"),
        ("nn", "%M"), ("ss", "%S")]


def Format(x, fmt=""):
    x, fmt = val(x), _s(fmt)
    if fmt == "":
        return _s(x)
    if isinstance(x, (_dt.datetime, _dt.date)) or re.search(r"[dy]", fmt, re.I) and not re.search(r"[0#]", fmt):
        out, i, low = "", 0, fmt.lower()
        while i < len(fmt):
            for tok, spec in _FMT:
                if low.startswith(tok, i):
                    out += _date(x).strftime(spec)
                    i += len(tok)
                    break
            else:
                if fmt[i].isalpha():
                    raise NotConverted("Format(..., %r): this format is not supported" % fmt)
                out += fmt[i]
                i += 1
        return out
    m = re.fullmatch(r"(#,##)?0(\.(0+))?", fmt)
    if not m:
        raise NotConverted("Format(..., %r): this format is not supported" % fmt)
    places = len(m.group(3) or "")
    q = 10 ** places
    v = int(abs(_n(x)) * q + 0.5) / q * (1 if _n(x) >= 0 else -1)      # Format rounds halves away from zero
    return format(v, (",.%df" if m.group(1) else ".%df") % places)


# ============================================================================= a tiny formula evaluator
_F_TOKEN = re.compile(r"""
    (?P<ws>\s+)
  | (?P<str>"(?:[^"]|"")*")
  | (?P<err>\#N/A|\#VALUE!|\#REF!|\#DIV/0!|\#NAME\?)
  | (?P<ref>(?:(?:'(?:[^']|'')+'|[A-Za-z_][\w.]*)!)?
        (?:\$?[A-Za-z]{1,3}\$?\d+(?::\$?[A-Za-z]{1,3}\$?\d+)?|\$?[A-Za-z]{1,3}:\$?[A-Za-z]{1,3})(?![\w(]))
  | (?P<num>\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+)
  | (?P<name>[A-Za-z_][\w.]*)
  | (?P<op><>|<=|>=|[=<>&+\-*/^(),%])
""", re.X)


class _Ref:
    def __init__(self, ws, r1, c1, r2, c2, whole):
        self.ws, self.r1, self.c1, self.r2, self.c2, self.whole = ws, r1, c1, r2, c2, whole

    def cells(self):
        last = min(self.r2, max(self.ws.max_row, self.r1))
        return [[(r, c) for c in range(self.c1, self.c2 + 1)] for r in range(self.r1, last + 1)]

    @property
    def single(self):
        return self.r1 == self.r2 and self.c1 == self.c2


def _xl_text(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (_dt.datetime, _dt.date)):
        v = _serial(v)
    if isinstance(v, float):
        return str(int(v)) if v.is_integer() and abs(v) < 1e15 else repr(float("%.15g" % v))
    return str(v)


def _xl_num(v):
    if isinstance(v, XlError):
        raise _Err(v)
    if v is None or v == "":
        return 0
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (_dt.datetime, _dt.date)):
        return _serial(v)
    if isinstance(v, str):
        try:
            return float(v)
        except ValueError:
            raise _Err(XlError("#VALUE!"))
    return v


def _xl_eq(a, b):
    if a is None:
        a = "" if isinstance(b, str) else 0
    if b is None:
        b = "" if isinstance(a, str) else 0
    if isinstance(a, str) != isinstance(b, str):
        return False
    return a.lower() == b.lower() if isinstance(a, str) else a == b


class _Err(Exception):
    def __init__(self, err):
        self.err = err


class _Calc:
    """Evaluates one cell's formula. Raises NotConverted for anything outside the supported list."""

    def __init__(self, book, ws, row, col, depth=0):
        self.book, self.ws, self.row, self.col, self.depth = book, ws, row, col, depth
        if depth > 50:
            raise NotConverted("formula chain deeper than 50 cells (circular reference?)")

    def run(self, formula):
        self.t = [(m.lastgroup, m.group(0)) for m in _F_TOKEN.finditer(formula[1:]) if m.lastgroup != "ws"]
        if sum(len(x[1]) for x in self.t) != len(re.sub(r"\s+", "", formula[1:])) and '"' not in formula:
            raise NotConverted("formula %s has text the evaluator cannot read" % formula)
        self.i, self.src = 0, formula
        try:
            v = self.scalar(self.cmp())
        except _Err as e:
            return e.err
        if self.i != len(self.t):
            raise NotConverted("formula %s: could not be read completely" % formula)
        return v

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else ("end", "")

    def op(self, *ops):
        return self.peek()[0] == "op" and self.peek()[1] in ops

    def cell(self, ws, r, c):
        v = ws.cell(r, c).value if r <= ws.max_row and c <= ws.max_column else None
        if isinstance(v, str) and v.startswith("=") and len(v) > 1:
            v = _Calc(self.book, ws, r, c, self.depth + 1).run(v)
        return v

    def scalar(self, v):
        if isinstance(v, _Ref):
            if not v.single:
                raise NotConverted("formula %s uses a multi-cell range where one value is expected" % self.src)
            v = self.cell(v.ws, v.r1, v.c1)
        if isinstance(v, XlError):
            raise _Err(v)
        return v

    def cmp(self):
        a = self.concat()
        while self.op("=", "<>", "<", ">", "<=", ">="):
            o = self.t[self.i][1]
            self.i += 1
            x, y = self.scalar(a), self.scalar(self.concat())
            if o in ("=", "<>"):
                a = _xl_eq(x, y) == (o == "=")
            else:
                x, y = (x.lower(), y.lower()) if isinstance(x, str) and isinstance(y, str) else (_xl_num(x), _xl_num(y))
                a = {"<": x < y, ">": x > y, "<=": x <= y, ">=": x >= y}[o]
        return a

    def concat(self):
        a = self.addsub()
        while self.op("&"):
            self.i += 1
            a = _xl_text(self.scalar(a)) + _xl_text(self.scalar(self.addsub()))
        return a

    def addsub(self):
        a = self.muldiv()
        while self.op("+", "-"):
            o = self.t[self.i][1]
            self.i += 1
            x, y = _xl_num(self.scalar(a)), _xl_num(self.scalar(self.muldiv()))
            a = x + y if o == "+" else x - y
        return a

    def muldiv(self):
        a = self.unary()
        while self.op("*", "/"):
            o = self.t[self.i][1]
            self.i += 1
            x, y = _xl_num(self.scalar(a)), _xl_num(self.scalar(self.unary()))
            if o == "/" and y == 0:
                raise _Err(XlError("#DIV/0!"))
            a = x * y if o == "*" else x / y
        return a

    def unary(self):
        if self.op("-"):
            self.i += 1
            return -_xl_num(self.scalar(self.unary()))
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        kind, text = self.peek()
        self.i += 1
        if kind == "num":
            f = float(text)
            return int(f) if f.is_integer() and "." not in text else f
        if kind == "str":
            return text[1:-1].replace('""', '"')
        if kind == "err":
            raise _Err(XlError(text))
        if kind == "ref":
            return self.ref(text)
        if kind == "op" and text == "(":
            v = self.cmp()
            self.i += 1
            return v
        if kind == "name":
            if text.upper() in ("TRUE", "FALSE") and not self.op("("):
                return text.upper() == "TRUE"
            if not self.op("("):
                raise NotConverted("formula %s uses the name %s (defined names are not supported)" % (self.src, text))
            self.i += 1
            return self.call(text.upper())
        raise NotConverted("formula %s: unexpected %r" % (self.src, text))

    def ref(self, text):
        ws = self.ws
        if "!" in text:
            sheet, text = text.rsplit("!", 1)
            sheet = sheet.strip("'").replace("''", "'")
            if sheet not in self.book.sheetnames:
                raise _Err(XlError("#REF!"))
            ws = self.book[sheet]
        a, _, b = text.replace("$", "").partition(":")
        m1, m2 = re.fullmatch(r"([A-Za-z]+)(\d*)", a), re.fullmatch(r"([A-Za-z]+)(\d*)", b or a)
        whole = not m1.group(2)
        return _Ref(ws, int(m1.group(2) or 1), column_index_from_string(m1.group(1).upper()),
                    int(m2.group(2) or MAX_ROW), column_index_from_string(m2.group(1).upper()), whole)

    def args(self, lazy=False):
        out = []
        if self.op(")"):
            self.i += 1
            return out
        while True:
            if self.op(",") or self.op(")"):
                out.append(None)
            elif lazy:
                start, depth = self.i, 0
                while not (depth == 0 and (self.op(",") or self.op(")"))):
                    depth += self.op("(") - self.op(")")
                    self.i += 1
                out.append((start, self.i))
            else:
                out.append(self.cmp())
            if self.op(","):
                self.i += 1
                continue
            self.i += 1
            return out

    def at(self, span):
        """Evaluate a lazily skipped argument."""
        keep, self.i = self.i, span[0]
        try:
            return self.cmp()
        finally:
            self.i = keep

    def column(self, ref):
        if not isinstance(ref, _Ref) or (ref.c1 != ref.c2 and ref.r1 != ref.r2):
            raise NotConverted("formula %s: a lookup range must be one column or one row" % self.src)
        return [(r, c) for row in ref.cells() for (r, c) in row]

    def call(self, name):
        if name in ("IF", "IFERROR", "IFNA"):
            a = self.args(lazy=True)
            if name == "IF":
                branch = a[1] if _xl_num(self.scalar(self.at(a[0]))) else (a[2] if len(a) > 2 else None)
                return False if branch is None and len(a) < 3 else (None if branch is None else self.at(branch))
            try:
                return self.scalar(self.at(a[0]))
            except _Err as e:
                if name == "IFNA" and e.err != NA:
                    raise
                return self.scalar(self.at(a[1])) if a[1] is not None else ""
        a = self.args()
        s = lambda k: self.scalar(a[k])
        if name == "RIGHT":
            n = int(_xl_num(s(1))) if len(a) > 1 else 1
            return _xl_text(s(0))[-n:] if n > 0 else ""
        if name == "LEFT":
            return _xl_text(s(0))[:int(_xl_num(s(1))) if len(a) > 1 else 1]
        if name == "MID":
            start = int(_xl_num(s(1))) - 1
            return _xl_text(s(0))[start:start + int(_xl_num(s(2)))]
        if name == "LEN":
            return len(_xl_text(s(0)))
        if name == "TRIM":
            return re.sub(r" +", " ", _xl_text(s(0))).strip(" ")
        if name in ("UPPER", "LOWER"):
            return _xl_text(s(0)).upper() if name == "UPPER" else _xl_text(s(0)).lower()
        if name in ("CONCATENATE", "CONCAT"):
            return "".join(_xl_text(self.scalar(x)) for x in a)
        if name == "VALUE":
            return _xl_num(s(0))
        if name == "ABS":
            return abs(_xl_num(s(0)))
        if name == "ROUND":
            q = 10 ** int(_xl_num(s(1)))
            v = _xl_num(s(0))
            return int(abs(v) * q + 0.5) / q * (1 if v >= 0 else -1)
        if name == "ISBLANK":
            return s(0) is None
        if name in ("AND", "OR"):
            vals = [bool(_xl_num(self.scalar(x))) for x in a]
            return all(vals) if name == "AND" else any(vals)
        if name == "NOT":
            return not _xl_num(s(0))
        if name == "SUM":
            total = 0
            for x in a:
                for v in ([self.cell(x.ws, r, c) for row in x.cells() for r, c in row] if isinstance(x, _Ref) else [x]):
                    if isinstance(v, XlError):
                        raise _Err(v)
                    total += v if isinstance(v, (int, float)) and not isinstance(v, bool) else 0
            return total
        if name == "COUNTIF":
            crit = s(1)
            n = 0
            for r, c in [p for row in a[0].cells() for p in row]:
                v = self.cell(a[0].ws, r, c)
                if isinstance(crit, str) and any(ch in crit for ch in "*?"):
                    n += isinstance(v, str) and fnmatch.fnmatchcase(v.lower(), crit.lower())
                elif isinstance(crit, str) and crit[:1] in "<>=":
                    raise NotConverted("COUNTIF with a comparison criterion is not supported")
                else:
                    n += v is not None and _xl_eq(v, crit)
            return n
        if name in ("XLOOKUP", "VLOOKUP", "MATCH"):
            key = s(0)
            if name == "XLOOKUP":
                if len(a) > 4 and any(x is not None and self.scalar(x) not in (0, 1) for x in a[4:]):
                    raise NotConverted("XLOOKUP with a match or search mode is not supported")
                look, ret = self.column(a[1]), self.column(a[2])
                for n, (r, c) in enumerate(look):
                    v = self.cell(a[1].ws, r, c)
                    if (key is None and _empty(v)) or (key is not None and v is not None and _xl_eq(v, key)):
                        return self.cell(a[2].ws, *ret[n]) if n < len(ret) else None
                if key is None and a[1].whole:
                    return None                          # the first empty cell below the data
                if len(a) > 3 and a[3] is not None:
                    return self.scalar(a[3])
                raise _Err(NA)
            if (len(a) < 4 or self.scalar(a[3]) not in (0, False)) if name == "VLOOKUP" else (len(a) < 3 or s(2) != 0):
                raise NotConverted("%s without exact match (last argument 0/FALSE) is not supported" % name)
            if name == "MATCH":
                for n, (r, c) in enumerate(self.column(a[1]), 1):
                    v = self.cell(a[1].ws, r, c)
                    if v is not None and _xl_eq(v, key):
                        return n
                raise _Err(NA)
            for row in a[1].cells():
                v = self.cell(a[1].ws, *row[0])
                if v is not None and _xl_eq(v, key):
                    return self.cell(a[1].ws, *row[int(_xl_num(s(2))) - 1])
            raise _Err(NA)
        if name == "INDEX":
            rows = a[0].cells()
            r, c = int(_xl_num(s(1))), int(_xl_num(s(2))) if len(a) > 2 and a[2] is not None else 1
            if len(rows) == 1 and len(a) < 3:
                r, c = 1, r
            return self.cell(a[0].ws, *rows[r - 1][c - 1])
        raise NotConverted("formula %s: the function %s is not in the evaluator's list" % (self.src, name))


def r1c1_to_a1(formula, row, col):
    """'=RC[-10]&" "&RC[-4]' at (row, col) -> '=AJ3&" "&AP3'. Text in quotes is left alone."""
    def ref(m):
        def part(kind, bracket, absolute, base):
            if bracket is not None:
                return (base + int(bracket), False)
            if absolute:
                return (int(absolute), True)
            return (base, False)
        r, r_abs = part("R", m.group(1), m.group(2), row)
        c, c_abs = part("C", m.group(3), m.group(4), col)
        if not (1 <= r <= MAX_ROW and 1 <= c <= MAX_COL):
            return "#REF!"
        return "%s%s%s%d" % ("$" if c_abs else "", get_column_letter(c), "$" if r_abs else "", r)
    out = []
    for i, chunk in enumerate(formula.split('"')):
        out.append(chunk if i % 2 else re.sub(r"\bR(?:\[(-?\d+)\]|(\d+))?C(?:\[(-?\d+)\]|(\d+))?(?![A-Za-z0-9_(])", ref, chunk))
    return '"'.join(out)


# ============================================================================= object model
def _rgb(bgr):
    bgr = int(_n(bgr))
    return "FF%02X%02X%02X" % (bgr & 255, (bgr >> 8) & 255, (bgr >> 16) & 255)


class Interior:
    """Fill of a range, or of a conditional format (dxf)."""

    def __init__(self, cells=None, rule=None):
        self._cells, self._rule = cells, rule
        self._color, self._theme, self._tint = None, None, 0
        self.PatternColorIndex = self.Pattern = None

    def _apply(self):
        if self._color is None and self._theme is None:
            return
        color = Color(rgb=self._color) if self._color else Color(theme=self._theme, tint=self._tint)
        if self._rule is not None:
            self._rule.dxf.fill = PatternFill(bgColor=color)
        else:
            for cell in self._cells():
                cell.fill = PatternFill(fill_type="solid", fgColor=color)

    @property
    def Color(self):
        return self._color

    @Color.setter
    def Color(self, bgr):
        self._color, self._theme = _rgb(bgr), None
        self._apply()

    @property
    def ThemeColor(self):
        return self._theme

    @ThemeColor.setter
    def ThemeColor(self, n):
        self._theme, self._color = int(_n(n)) - 1, None        # xlThemeColorDark1 = 1 is theme colour 0 in the file
        self._apply()

    @property
    def TintAndShade(self):
        return self._tint

    @TintAndShade.setter
    def TintAndShade(self, t):
        self._tint = float(_n(t))
        self._apply()

    @property
    def ColorIndex(self):
        raise NotConverted("ColorIndex depends on the workbook's colour palette")

    @ColorIndex.setter
    def ColorIndex(self, v):
        if int(_n(v)) != -4142:
            raise NotConverted("ColorIndex depends on the workbook's colour palette")
        if self._rule is None:
            for cell in self._cells():
                cell.fill = PatternFill(fill_type=None)


class FontX:
    def __init__(self, cells=None, rule=None):
        self._cells, self._rule = cells, rule

    def _set(self, **kw):
        if self._rule is not None:
            f = self._rule.dxf.font or Font()
            self._rule.dxf.font = Font(b=kw.get("b", f.b), i=kw.get("i", f.i), color=kw.get("color", f.color))
        else:
            for cell in self._cells():
                f = copy(cell.font)
                for k, v in kw.items():
                    setattr(f, k, v)
                cell.font = f

    Bold = property(lambda self: None, lambda self, v: self._set(b=truth(v)))
    Italic = property(lambda self: None, lambda self, v: self._set(i=truth(v)))
    Color = property(lambda self: None, lambda self, v: self._set(color=Color(rgb=_rgb(v))))


class FormatCondition:
    def __init__(self, ws, rule):
        self._ws, self._rule = ws, rule
        self.Interior, self.Font = Interior(rule=rule), FontX(rule=rule)

    StopIfTrue = property(lambda self: bool(self._rule.stopIfTrue),
                          lambda self, v: setattr(self._rule, "stopIfTrue", truth(v)))
    Priority = property(lambda self: self._rule.priority)

    def SetFirstPriority(self):
        old = self._rule.priority
        for cf in self._ws.conditional_formatting:
            for r in cf.rules:
                if r is not self._rule and r.priority < old:
                    r.priority += 1
        self._rule.priority = 1

    def Delete(self):
        for cf in self._ws.conditional_formatting:
            if self._rule in cf.rules:
                cf.rules.remove(self._rule)


class FormatConditions:
    def __init__(self, rng):
        self._rng = rng

    def _rules(self):
        ws, out = self._rng._ws, []
        for cf in ws.conditional_formatting:
            if any(not (cr.max_row < self._rng.r1 or cr.min_row > self._rng.r2 or cr.max_col < self._rng.c1
                        or cr.min_col > self._rng.c2) for cr in cf.sqref.ranges):
                out += list(cf.rules)
        return sorted(out, key=lambda r: r.priority)

    Count = property(lambda self: len(self._rules()))

    def __call__(self, index):
        rules = self._rules()
        i = int(_n(index))
        if not 1 <= i <= len(rules):
            raise IndexError("FormatConditions(%d): there are %d" % (i, len(rules)))
        return FormatCondition(self._rng._ws, rules[i - 1])

    Item = __call__

    def Add(self, Type, Operator=None, Formula1=None, Formula2=None):
        ws = self._rng._ws
        top = max([r.priority for cf in ws.conditional_formatting for r in cf.rules] or [0])
        formulas = [_s(f)[1:] if _s(f).startswith("=") else _s(f) for f in (Formula1, Formula2) if f is not None]
        if int(_n(Type)) == xlExpression:
            rule = Rule(type="expression", formula=formulas[:1], dxf=DifferentialStyle(), priority=top + 1)
        elif int(_n(Type)) == xlCellValue:
            rule = Rule(type="cellIs", operator=_OPERATORS[int(_n(Operator))], formula=formulas, dxf=DifferentialStyle(),
                        priority=top + 1)
        else:
            raise NotConverted("FormatConditions.Add Type:=%s is not supported" % Type)
        ws.conditional_formatting.add(self._rng.Address.replace("$", ""), rule)
        self._rng._book._dirty = True
        return FormatCondition(ws, rule)

    def Delete(self):
        for r in self._rules():
            FormatCondition(self._rng._ws, r).Delete()


class Rng:
    """A rectangular range of one sheet (1-based, inclusive)."""

    def __init__(self, sheet, r1, c1, r2, c2):
        self._sheet, self._ws, self._book = sheet, sheet._ws, sheet._book
        self.r1, self.c1, self.r2, self.c2 = r1, c1, r2, c2

    # ---- geometry
    def _clip(self, extra_rows=0):
        """Whole-column / whole-row ranges are cut down to the used area."""
        r2 = min(self.r2, max(self._ws.max_row, self.r1, extra_rows)) if self.r2 == MAX_ROW else self.r2
        c2 = min(self.c2, max(self._ws.max_column, self.c1)) if self.c2 == MAX_COL else self.c2
        return r2, c2

    def _cells(self, extra_rows=0):
        r2, c2 = self._clip(extra_rows)
        if (r2 - self.r1 + 1) * (c2 - self.c1 + 1) > 3000000:
            raise NotConverted("range %s is too large to process cell by cell" % self.Address)
        for r in range(self.r1, r2 + 1):
            for c in range(self.c1, c2 + 1):
                yield self._ws.cell(r, c)

    Row = property(lambda self: self.r1)
    Column = property(lambda self: self.c1)
    Count = property(lambda self: (self.r2 - self.r1 + 1) * (self.c2 - self.c1 + 1))
    Worksheet = property(lambda self: self._sheet)
    Parent = Worksheet
    Columns = property(lambda self: self)
    Rows = property(lambda self: self)
    EntireRow = property(lambda self: Rng(self._sheet, self.r1, 1, self.r2, MAX_COL))
    EntireColumn = property(lambda self: Rng(self._sheet, 1, self.c1, MAX_ROW, self.c2))
    FormatConditions = property(lambda self: FormatConditions(self))
    Interior = property(lambda self: Interior(cells=self._cells))
    Font = property(lambda self: FontX(cells=self._cells))

    @property
    def Address(self):
        a = "$%s$%d" % (get_column_letter(self.c1), self.r1)
        b = "$%s$%d" % (get_column_letter(self.c2), self.r2)
        if self.r1 == 1 and self.r2 == MAX_ROW:
            return "$%s:$%s" % (get_column_letter(self.c1), get_column_letter(self.c2))
        if self.c1 == 1 and self.c2 == MAX_COL:
            return "$%d:$%d" % (self.r1, self.r2)
        return a if a == b else a + ":" + b

    def Cells(self, row, col):
        col = column_index_from_string(col.upper()) if isinstance(col, str) else int(_n(col))
        r, c = self.r1 + int(_n(row)) - 1, self.c1 + col - 1
        return Rng(self._sheet, r, c, r, c)

    def Offset(self, RowOffset=0, ColumnOffset=0):
        dr, dc = int(_n(RowOffset)), int(_n(ColumnOffset))
        return Rng(self._sheet, self.r1 + dr, self.c1 + dc, self.r2 + dr, self.c2 + dc)

    def Resize(self, RowSize=None, ColumnSize=None):
        return Rng(self._sheet, self.r1, self.c1, self.r1 + int(_n(RowSize)) - 1 if RowSize is not None else self.r2,
                   self.c1 + int(_n(ColumnSize)) - 1 if ColumnSize is not None else self.c2)

    def End(self, Direction):
        """Ctrl+arrow from the first cell of the range."""
        dr, dc = {xlUp: (-1, 0), xlDown: (1, 0), xlToLeft: (0, -1), xlToRight: (0, 1)}[int(_n(Direction))]
        ws, r, c = self._ws, self.r1, self.c1
        filled = lambda rr, cc: 1 <= rr <= ws.max_row and 1 <= cc <= ws.max_column and ws.cell(rr, cc).value is not None
        inside = lambda rr, cc: 1 <= rr <= MAX_ROW and 1 <= cc <= MAX_COL
        if filled(r, c) and filled(r + dr, c + dc):
            while filled(r + dr, c + dc):
                r, c = r + dr, c + dc
            return Rng(self._sheet, r, c, r, c)
        limit_r = ws.max_row + 1 if dr > 0 else 0
        limit_c = ws.max_column + 1 if dc > 0 else 0
        r, c = r + dr, c + dc
        while inside(r, c) and not filled(r, c):
            if (dr and (r >= limit_r if dr > 0 else r <= 0)) or (dc and (c >= limit_c if dc > 0 else c <= 0)):
                break
            if dr < 0 and r > ws.max_row:
                r = ws.max_row + 1                       # jump over the empty area below the data
            if dc < 0 and c > ws.max_column:
                c = ws.max_column + 1
            r, c = r + dr, c + dc
        if not inside(r, c) or not filled(r, c):
            r = (MAX_ROW if dr > 0 else 1) if dr else r
            c = (MAX_COL if dc > 0 else 1) if dc else c
        return Rng(self._sheet, r, c, r, c)

    def __iter__(self):
        for cell in self._cells():
            yield Rng(self._sheet, cell.row, cell.column, cell.row, cell.column)

    # ---- values and formulas
    def _value(self, cell):
        v = cell.value
        if isinstance(v, str) and v.startswith("=") and len(v) > 1:
            cached = self._book._cached(self._ws.title, cell.row, cell.column)
            return cached if cached is not _MISSING else _Calc(self._book._wb, self._ws, cell.row, cell.column).run(v)
        return v

    @property
    def Value(self):
        if self.r1 == self.r2 and self.c1 == self.c2:
            return self._value(self._ws.cell(self.r1, self.c1)) if self.r1 <= self._ws.max_row else None
        r2, c2 = self._clip()
        return [[self._value(self._ws.cell(r, c)) for c in range(self.c1, c2 + 1)] for r in range(self.r1, r2 + 1)]

    @Value.setter
    def Value(self, v):
        v = val(v)
        self._book._dirty = True
        if self.Count > 3000000 and (self.r2 == MAX_ROW or self.c2 == MAX_COL):
            raise NotConverted("writing to the whole column/row %s is not supported" % self.Address)
        if isinstance(v, list):
            for i, row in enumerate(v):
                for j, x in enumerate(row if isinstance(row, list) else [row]):
                    if self.r1 + i <= self.r2 and self.c1 + j <= self.c2:
                        self._ws.cell(self.r1 + i, self.c1 + j).value = None if x == "" else x
        else:
            v = None if v == "" else v                    # assigning "" leaves the cell empty, as in Excel
            for cell in self._cells():
                cell.value = v

    Value2 = Value

    @property
    def Text(self):
        return _xl_text(self.Value)

    @property
    def Formula(self):
        v = self._ws.cell(self.r1, self.c1).value
        return "" if v is None else v

    @Formula.setter
    def Formula(self, f):
        f = _s(f)
        self._book._dirty = True
        origin = "%s%d" % (get_column_letter(self.c1), self.r1)
        for cell in self._cells():
            cell.value = Translator(f, origin=origin).translate_formula(cell.coordinate) if f.startswith("=") else f

    @property
    def FormulaR1C1(self):
        raise NotConverted("reading FormulaR1C1 is not supported")

    @FormulaR1C1.setter
    def FormulaR1C1(self, f):
        f = _s(f)
        self._book._dirty = True
        for cell in self._cells():
            cell.value = r1c1_to_a1(f, cell.row, cell.column) if f.startswith("=") else f

    def ClearContents(self):
        self._book._dirty = True
        r2, c2 = self._clip()
        for r in range(self.r1, min(r2, self._ws.max_row) + 1):
            for c in range(self.c1, min(c2, self._ws.max_column) + 1):
                self._ws.cell(r, c).value = None

    def Clear(self):
        self.ClearContents()
        for cell in self._cells():
            cell.style = "Normal"

    def Delete(self, Shift=None):
        if not (self.c1 == 1 and self.c2 == MAX_COL):
            raise NotConverted("Delete is supported for entire rows only (%s)" % self.Address)
        self._book._dirty = True
        last = min(self.r2, self._ws.max_row)
        if last >= self.r1:
            self._ws.delete_rows(self.r1, last - self.r1 + 1)

    # ---- clipboard
    def Copy(self, Destination=None):
        if Destination is None:
            self._sheet._app._clipboard = self
        else:
            _paste(self, Destination, xlPasteAll)

    def PasteSpecial(self, Paste=xlPasteAll, Operation=None, SkipBlanks=False, Transpose=False):
        if truth(SkipBlanks) or truth(Transpose) or (Operation is not None and int(_n(Operation)) != -4142):
            raise NotConverted("PasteSpecial with Operation, SkipBlanks or Transpose is not supported")
        src = self._sheet._app._clipboard
        if src is None:
            raise RuntimeError("PasteSpecial: nothing has been copied")
        _paste(src, self, int(_n(Paste)))

    # ---- selection and layout
    def Select(self):
        self._sheet._app._select(self)

    Activate = Select

    def AutoFit(self):
        """Approximation: Excel measures rendered text; this uses the longest text in each column."""
        self._book._dirty = True
        r2, c2 = self._clip()
        for c in range(self.c1, c2 + 1):
            longest = max([len(_xl_text(self._ws.cell(r, c).value)) for r in range(self.r1, min(r2, self._ws.max_row) + 1)] or [0])
            if longest:
                self._ws.column_dimensions[get_column_letter(c)].width = min(longest + 2, 255)
        self._sheet._app.log.append("AutoFit %s!%s: widths estimated, not measured" % (self._ws.title, self.Address))

    NumberFormat = property(lambda self: self._ws.cell(self.r1, self.c1).number_format,
                            lambda self, f: [setattr(c, "number_format", _s(f)) for c in self._cells()] and None)


_MISSING = object()


def _paste(src, dst, mode):
    if mode not in (xlPasteAll, xlPasteValues, xlPasteFormats, xlPasteFormulas):
        raise NotConverted("paste type %s is not supported" % mode)
    dst._book._dirty = True
    r2, c2 = src._clip()
    same_book = src._book is dst._book
    for r in range(src.r1, r2 + 1):
        for c in range(src.c1, c2 + 1):
            s = src._ws.cell(r, c) if r <= src._ws.max_row and c <= src._ws.max_column else None
            t = dst._ws.cell(dst.r1 + r - src.r1, dst.c1 + c - src.c1)
            if mode == xlPasteValues:
                t.value = None if s is None else src._value(s)
                continue
            if mode in (xlPasteAll, xlPasteFormulas):
                v = None if s is None else s.value
                if isinstance(v, str) and v.startswith("=") and len(v) > 1:
                    v = Translator(v, origin=s.coordinate).translate_formula(t.coordinate)
                t.value = v
            if mode in (xlPasteAll, xlPasteFormats) and s is not None and s.has_style:
                if same_book:
                    t._style = copy(s._style)
                else:
                    t.font, t.fill, t.border = copy(s.font), copy(s.fill), copy(s.border)
                    t.alignment, t.number_format, t.protection = copy(s.alignment), s.number_format, copy(s.protection)


def _parse_address(text):
    """'A2:AS5000', 'B2', 'AT:AX', '3:20000' -> (r1, c1, r2, c2)"""
    text = text.replace("$", "").strip()
    if "," in text or " " in text or "!" in text:
        raise NotConverted("range address %r (several areas, intersections or sheet names) is not supported" % text)
    a, _, b = text.partition(":")
    b = b or a
    out = []
    for part in (a, b):
        m = re.fullmatch(r"([A-Za-z]{0,3})(\d*)", part)
        if not m or not part:
            raise NotConverted("range address %r is not a plain cell address (defined names are not supported)" % text)
        out.append((int(m.group(2)) if m.group(2) else None, column_index_from_string(m.group(1).upper()) if m.group(1) else None))
    (r1, c1), (r2, c2) = out
    return (r1 or 1, c1 or 1, r2 or MAX_ROW, c2 or MAX_COL)


class _Axis:
    """ws.Rows / ws.Columns: has .Count and can be called with "3:20000" or "AT:AX" or an index."""

    def __init__(self, sheet, rows):
        self._sheet, self._rows = sheet, rows

    Count = property(lambda self: MAX_ROW if self._rows else MAX_COL)

    def __call__(self, index):
        index = val(index)
        if isinstance(index, str):
            r1, c1, r2, c2 = _parse_address(index if ":" in index else index + ":" + index)
        elif self._rows:
            r1, c1, r2, c2 = int(index), 1, int(index), MAX_COL
        else:
            r1, c1, r2, c2 = 1, int(index), MAX_ROW, int(index)
        return Rng(self._sheet, r1, c1, r2, c2)


class _CellsProxy:
    def __init__(self, sheet):
        self._sheet = sheet

    def __call__(self, row, col):
        col = val(col)
        c = column_index_from_string(col.upper()) if isinstance(col, str) else int(_n(col))
        return Rng(self._sheet, int(_n(row)), c, int(_n(row)), c)

    def __getattr__(self, name):                       # Cells.ClearContents, Cells.Select, ...
        return getattr(Rng(self._sheet, 1, 1, MAX_ROW, MAX_COL), name)


class Sheet:
    def __init__(self, book, ws):
        self._book, self._ws, self._app = book, ws, book._app

    Name = property(lambda self: self._ws.title)
    Parent = property(lambda self: self._book)
    Cells = property(lambda self: _CellsProxy(self))
    Rows = property(lambda self: _Axis(self, True))
    Columns = property(lambda self: _Axis(self, False))

    def Range(self, a, b=None):
        a, b = (x if isinstance(x, Rng) else (None if x is None else _s(x)) for x in (a, b))
        ra = (a.r1, a.c1, a.r2, a.c2) if isinstance(a, Rng) else _parse_address(a)
        if b is None:
            return Rng(self, *ra)
        rb = (b.r1, b.c1, b.r2, b.c2) if isinstance(b, Rng) else _parse_address(b)
        return Rng(self, min(ra[0], rb[0]), min(ra[1], rb[1]), max(ra[2], rb[2]), max(ra[3], rb[3]))

    @property
    def UsedRange(self):
        return Rng(self, self._ws.min_row, self._ws.min_column, self._ws.max_row, self._ws.max_column)

    def Activate(self):
        self._book.Activate()
        self._book._active = self
        self._app.Selection = Rng(self, 1, 1, 1, 1)

    Select = Activate

    @property
    def AutoFilterMode(self):
        return bool(self._ws.auto_filter.ref)

    @AutoFilterMode.setter
    def AutoFilterMode(self, v):
        if truth(v):
            raise NotConverted("AutoFilterMode can only be set to False")
        self._ws.auto_filter.ref = None
        self._book._dirty = True

    def Paste(self, Destination=None):
        src = self._app._clipboard
        if src is None:
            raise RuntimeError("Paste: nothing has been copied")
        _paste(src, Destination if Destination is not None else self._app.Selection, xlPasteAll)


class Book:
    def __init__(self, app, path, wb):
        self._app, self._path, self._wb = app, path, wb
        self._sheets = {}
        self._active = self._sheet(wb.active)
        self._dirty, self._values, self.saved = False, None, 0

    def _sheet(self, ws):
        return self._sheets.setdefault(ws.title, Sheet(self, ws))

    def _cached(self, title, row, col):
        """The value Excel last calculated for a formula cell, while this workbook is untouched."""
        if self._dirty or not self._path or not os.path.exists(self._path):
            return _MISSING
        if self._values is None:
            self._values = openpyxl.load_workbook(self._path, data_only=True)
        v = self._values[title].cell(row, col).value if title in self._values.sheetnames else None
        if isinstance(v, str) and v.startswith("#") and v in ("#N/A", "#VALUE!", "#REF!", "#DIV/0!", "#NAME?"):
            return XlError(v)
        return _MISSING if v is None else v

    Name = property(lambda self: os.path.basename(self._path))
    FullName = property(lambda self: self._path)
    Path = property(lambda self: os.path.dirname(self._path))
    ActiveSheet = property(lambda self: self._active)

    def Sheets(self, index):
        index = val(index)
        if isinstance(index, str):
            for name in self._wb.sheetnames:
                if name.lower() == index.lower():
                    return self._sheet(self._wb[name])
            raise IndexError("Subscript out of range: no sheet named %r in %s" % (index, self.Name))
        return self._sheet(self._wb.worksheets[int(_n(index)) - 1])

    Worksheets = Sheets

    def Activate(self):
        self._app._activate(self)

    def Save(self):
        self.saved += 1
        if self._app.save:
            self._wb.save(self._path)
            self._values = None
        self._app.log.append("%s %s" % ("saved" if self._app.save else "would save (save=False)", self._path))

    def SaveAs(self, Filename, FileFormat=None):
        self._path = self._app._full(_s(Filename))
        self.Save()

    def Close(self, SaveChanges=None):
        if SaveChanges is not None and truth(SaveChanges):
            self.Save()
        elif SaveChanges is None and self._dirty and not self.saved and self._app.DisplayAlerts:
            raise NotConverted("Close of a changed workbook without SaveChanges would show Excel's save prompt")
        self._app._closed(self)


class Workbooks:
    def __init__(self, app):
        self._app = app

    Count = property(lambda self: len(self._app._books))

    def __call__(self, index):
        index = val(index)
        if isinstance(index, str):
            for b in self._app._books:
                if b.Name.lower() == index.lower():
                    return b
            raise IndexError("Subscript out of range: workbook %r is not open" % index)
        return self._app._books[int(_n(index)) - 1]

    def Open(self, Filename, UpdateLinks=None, ReadOnly=None, **other):
        path = self._app._full(_s(Filename))
        if not os.path.exists(path):
            raise FileNotFoundError("Sorry, we couldn't find %s. Is it possible it was moved, renamed or deleted?" % path)
        if os.path.splitext(path)[1].lower() not in (".xlsx", ".xlsm"):
            raise NotConverted("only .xlsx and .xlsm workbooks can be opened (%s)" % path)
        book = Book(self._app, path, openpyxl.load_workbook(path, keep_vba=path.lower().endswith(".xlsm")))
        self._app._books.append(book)
        self._app._activate(book)
        return book


class ErrObject:
    def __init__(self, exc=None):
        self.Description = "" if exc is None else str(exc)
        self.Number = 0 if exc is None else 1004
        self.exc = exc

    def Clear(self):
        self.__init__()


class App:
    """Stands in for Excel's Application while a converted macro runs.

    macro_workbook: the .xlsm the macros live in (ThisWorkbook). save=False never writes a file:
    Save calls are only recorded in app.log."""

    def __init__(self, macro_workbook, save=False, base_dir=None, now=None):
        self.save, self.log, self._books, self._order = save, [], [], []
        self.base_dir = base_dir or os.path.dirname(os.path.abspath(macro_workbook))
        self._clipboard, self.Selection, self.Err, self.now = None, None, ErrObject(), now
        self.DisplayAlerts = self.ScreenUpdating = self.EnableEvents = True
        self.Calculation = self.CutCopyMode = self.StatusBar = None
        self.Workbooks = Workbooks(self)
        self.ThisWorkbook = self.Workbooks.Open(macro_workbook)
        self.ThisWorkbook._active.Activate()

    Application = property(lambda self: self)

    def _full(self, path):
        path = path.replace("\\", os.sep) if os.sep == "/" else path
        return path if os.path.isabs(path) or re.match(r"^[A-Za-z]:", path) else os.path.join(self.base_dir, path)

    def _activate(self, book):
        if book in self._order:
            self._order.remove(book)
        self._order.append(book)
        self.Selection = Rng(book._active, 1, 1, 1, 1)

    def _closed(self, book):
        self._books.remove(book)
        self._order.remove(book)
        if self._order:
            self.Selection = Rng(self._order[-1]._active, 1, 1, 1, 1)

    def _select(self, rng):
        if rng._sheet is not self.ActiveSheet:
            raise RuntimeError("Select method of Range class failed: %s is not the active sheet" % rng._ws.title)
        self.Selection = rng

    @property
    def ActiveWorkbook(self):
        if not self._order:
            raise RuntimeError("no workbook is open")
        return self._order[-1]

    ActiveSheet = property(lambda self: self.ActiveWorkbook._active)
    ActiveCell = property(lambda self: Rng(self.Selection._sheet, self.Selection.r1, self.Selection.c1,
                                           self.Selection.r1, self.Selection.c1))
    Cells = property(lambda self: self.ActiveSheet.Cells)
    Rows = property(lambda self: self.ActiveSheet.Rows)
    Columns = property(lambda self: self.ActiveSheet.Columns)

    def Sheets(self, index):
        return self.ActiveWorkbook.Sheets(index)

    Worksheets = Sheets

    def Range(self, a, b=None):
        return self.ActiveSheet.Range(a, b)

    def Evaluate(self, text):
        """[B2] -> the cell on the active sheet. Bracketed formulas are not supported."""
        try:
            return self.ActiveSheet.Range(text)
        except NotConverted:
            raise NotConverted("[%s]: only plain cell addresses are supported inside square brackets" % text)

    def MsgBox(self, Prompt, Buttons=0, Title=""):
        self.log.append("MsgBox: %s" % _s(Prompt))
        if int(_n(Buttons)) & 7:
            raise NotConverted("MsgBox with a choice of buttons needs a person to answer")
        return 1

    def InputBox(self, *a, **k):
        raise NotConverted("InputBox needs a person to answer")

    def CreateObject(self, name):
        raise NotConverted("CreateObject(%r): automation of another program (Outlook, Word, a file-system object, ...) "
                           "has no deterministic equivalent here" % _s(name))

    GetObject = CreateObject

    def Now(self):
        return self.now or _dt.datetime.now().replace(microsecond=0)

    def Date(self):
        n = self.Now()
        return _dt.datetime(n.year, n.month, n.day)

    def Dir(self, pattern="", attributes=0):
        full = self._full(_s(pattern))
        folder, pat = os.path.split(full)
        names = sorted(n for n in os.listdir(folder or ".") if fnmatch.fnmatch(n.lower(), pat.lower())) \
            if os.path.isdir(folder or ".") else []
        return names[0] if names else ""

    class _Resume:
        def __init__(self, app):
            self.app = app

        def __enter__(self):
            return self

        def __exit__(self, kind, exc, tb):
            if exc is not None and isinstance(exc, Exception):
                self.app.Err = ErrObject(exc)
                return True
            return False

    def ResumeNext(self):
        """On Error Resume Next: a failing statement is skipped and recorded in Err."""
        return App._Resume(self)
